using Microsoft.Data.Sqlite;
using Salryn.Api.Local.Services;
using Salryn.Composition.Local;
using Salryn.Infrastructure.Data;
using Salryn.Infrastructure.Paths;

namespace Salryn.Tests;

public static class W4CashDrawerReconciliationChecks
{
    public static void Run()
    {
        string root=Path.Combine(Path.GetTempPath(),"salryn-w4-"+Guid.NewGuid().ToString("N"));
        try{SalrynLocalComposition c=SalrynLocalComposition.Create(DbPaths.CreateDevelopment(root));Require(c.DatabaseInitialization.InitializeDatabase().IsSuccess,"v25 initialization must pass");Guid user=SeedUser(c);HostOperatorApiServices host=HostOperatorApiServices.Create(c);CashDrawerReconciliationService drawer=new(c);
            var opened=host.ShiftService.OpenShiftAsync(user,10_000).GetAwaiter().GetResult();Require(opened.Ok,"nonzero opening float must open");string session=opened.Shift!.ShiftId!;
            var cashIn=drawer.RecordMovement(user,new("CashIn",2_000,"in-1","Documented float add"));Require(cashIn.IsSuccess&&cashIn.Value.ExpectedCashCents==12_000,"cash-in must increase expected");
            var replay=drawer.RecordMovement(user,new("CashIn",2_000,"in-1","Documented float add"));Require(replay.IsSuccess&&Count(c,"cash_drawer_events")==1,"movement replay must not duplicate");
            Require(drawer.RecordMovement(user,new("CashIn",2_001,"in-1","Documented float add")).IsFailure,"movement request replay with changed data must fail");
            Require(drawer.RecordMovement(user,new("CashOut",500,"out-1","Documented payout")).IsSuccess,"cash-out must record");Require(drawer.RecordMovement(user,new("CashRefund",300,"refund-1","Actual cash refund")).IsSuccess,"actual refund must record");
            Require(drawer.RecordMovement(user,new("CashIn",-1,"bad","bad")).IsFailure,"negative movement must fail");
            Require(drawer.Close(user,new(-1,true,"negative-close",null)).IsFailure,"negative physical count must fail");
            Guid otherUser=SeedUser(c,"w4-other");Require(drawer.Read(otherUser).IsFailure&&drawer.Close(otherUser,new(0,true,"other-close",null)).IsFailure,"cashier must not read or close another cashier's shift");
            var close=drawer.Close(user,new(11_100,true,"close-1","Physical count"));Require(close.IsSuccess&&close.Value.ExpectedCashCents==11_200&&close.Value.VarianceCents==-100&&close.Value.ReviewStatus=="PendingReview","shortage must close pending review with true variance");
            var restartedDrawer=new CashDrawerReconciliationService(c);Require(restartedDrawer.Close(user,new(11_100,true,"close-1","Physical count")).IsSuccess&&Count(c,"cash_drawer_reconciliations")==1,"persisted close replay after service restart must reconcile without duplicate");
            Require(restartedDrawer.Close(user,new(100_000,true,"close-1","Physical count")).IsFailure,"close replay with changed count must conflict");Require(restartedDrawer.Close(user,new(11_100,true,"close-1","Changed note")).IsFailure,"close replay with changed note must conflict");Require(Scalar(c,"SELECT counted_cash_cents FROM cash_drawer_reconciliations WHERE cashier_session_id=$id",("$id",session))==11_100,"changed replay must not mutate original count");Require(drawer.Close(user,new(11_100,true,"close-2",null)).IsFailure,"second close must fail");
            Guid manager=SeedUser(c,"w4-manager");Require(drawer.Review(user,Guid.Parse(session),new("Acknowledged","Self review","self-review")).IsFailure,"count submitter must not review own discrepancy");var review=drawer.Review(manager,Guid.Parse(session),new("Acknowledged","Manager investigated shortage","review-1"));Require(review.IsSuccess&&review.Value.ReviewStatus=="Acknowledged"&&review.Value.CountedCashCents==11_100,"review must append without rewriting count");Require(Count(c,"cash_drawer_reviews")==1,"one immutable review expected");
            Require(drawer.Review(manager,Guid.Parse(session),new("Acknowledged","Manager investigated shortage","review-1")).IsSuccess&&Count(c,"cash_drawer_reviews")==1,"review replay must not duplicate");
            Require(drawer.Review(manager,Guid.Parse(session),new("Acknowledged","Changed reason","review-1")).IsFailure,"review request replay with changed data must fail");
            var second=host.ShiftService.OpenShiftAsync(user,0).GetAwaiter().GetResult();Require(second.Ok,"zero opening float must open");Require(drawer.Close(user,new(0,true,"close-zero",null)).Value.ReviewStatus=="Reconciled","verified zero variance must reconcile");
            Require(host.ShiftService.OpenShiftAsync(user,100).GetAwaiter().GetResult().Ok,"overage shift must open");var overage=drawer.Close(user,new(125,true,"close-overage",null));Require(overage.IsSuccess&&overage.Value.VarianceCents==25&&overage.Value.ReviewStatus=="PendingReview","overage must close pending review");
            Guid legacy=Guid.NewGuid();Exec(c,"INSERT INTO cashier_sessions(id,user_id,opened_at,opening_cash_cents,expected_cash_cents,variance_cents,status,notes,cash_coverage_started_at) VALUES($id,$user,$at,0,0,0,1,'legacy',NULL)",( "$id",legacy.ToString("D")),("$user",user.ToString("D")),("$at",DateTimeOffset.UtcNow.ToString("O")));Require(drawer.Close(user,new(0,true,"legacy-close",null)).IsFailure,"legacy unverified coverage must fail closed");
            RunSourceEqualityChecks(c,drawer,host,session);
            var history=drawer.ReadClosedHistory(10,0);Require(history.IsSuccess&&history.Value.Items.Count>=3&&history.Value.Items.Any(x=>x.SessionId==session),"authorized history service must return bounded closed-shift detail");Require(drawer.ReadClosedHistory(101,0).IsFailure,"history page must be bounded");
            string remote=File.ReadAllText(Path.Combine(Root(),"src","Salryn.Api.Local","RemotePos","RemotePosCheckoutService.cs"));Require(remote.Contains("PhysicalCountRequired",StringComparison.Ordinal)&&!remote.Contains("open.ExpectedCash, \"Remote POS shift close\"",StringComparison.Ordinal),"remote auto-balance bypass must be removed");
            Require(Scalar(c,"SELECT counted_cash_cents FROM cashier_sessions WHERE id=$id",("$id",session))==11_100,"physical count must persist exactly");RunV25ToV26MigrationCheck();Console.WriteLine("W4 cash drawer PASS: canonical close replay, source-by-source sale/AR equality, history authority, physical count, discrepancy review, legacy fail-closed, and v25-to-v26 migration.");
        }finally{SqliteConnectionFactory.ClearAllPools();if(Directory.Exists(root))Directory.Delete(root,true);}
    }
    private static void RunSourceEqualityChecks(SalrynLocalComposition c,CashDrawerReconciliationService drawer,HostOperatorApiServices host,string otherSession)
    {
        Guid user=SeedUser(c,"w4-source");var opened=host.ShiftService.OpenShiftAsync(user,0).GetAwaiter().GetResult();Require(opened.Ok,"source verification shift must open");string session=opened.Shift!.ShiftId!;Guid sale=Guid.NewGuid();string now=DateTimeOffset.UtcNow.ToString("O");
        Exec(c,"INSERT INTO sales(id,receipt_no,sale_date,cashier_user_id,cashier_session_id,subtotal_cents,discount_cents,tax_cents,total_cents,amount_paid_cents,change_cents,status,created_at) VALUES($id,$receipt,$at,$user,$session,500,0,0,500,700,200,1,$at)",("$id",sale.ToString("D")),("$receipt","W4-"+sale.ToString("N")),("$at",now),("$user",user.ToString("D")),("$session",session));Exec(c,"INSERT INTO payments(id,sale_id,method,amount_cents,paid_at) VALUES($id,$sale,1,700,$at)",("$id",Guid.NewGuid().ToString("D")),("$sale",sale.ToString("D")),("$at",now));InsertSourceEvent(c,session,"CashSaleNet",1,500,"Sale",sale.ToString("D"),user,"Cash","sale-fixture");
        AssertTamperBlocked(c,drawer,user,"UPDATE cash_drawer_events SET amount_cents=499 WHERE request_id='sale-fixture'","UPDATE cash_drawer_events SET amount_cents=500 WHERE request_id='sale-fixture'","sale amount");AssertTamperBlocked(c,drawer,user,"UPDATE cash_drawer_events SET direction=-1 WHERE request_id='sale-fixture'","UPDATE cash_drawer_events SET direction=1 WHERE request_id='sale-fixture'","sale direction");AssertTamperBlocked(c,drawer,user,"UPDATE cash_drawer_events SET method='Card' WHERE request_id='sale-fixture'","UPDATE cash_drawer_events SET method='Cash' WHERE request_id='sale-fixture'","sale method");AssertTamperBlocked(c,drawer,user,"UPDATE cash_drawer_events SET source_id='spoof' WHERE request_id='sale-fixture'","UPDATE cash_drawer_events SET source_id=$source WHERE request_id='sale-fixture'","sale source",("$source",sale.ToString("D")));AssertTamperBlocked(c,drawer,user,"UPDATE cash_drawer_events SET actor_user_id=$other WHERE request_id='sale-fixture'","UPDATE cash_drawer_events SET actor_user_id=$user WHERE request_id='sale-fixture'","sale actor",("$other",SeedUser(c,"w4-spoof").ToString("D")),("$user",user.ToString("D")));AssertTamperBlocked(c,drawer,user,"UPDATE cash_drawer_events SET cashier_session_id=$other WHERE request_id='sale-fixture'","UPDATE cash_drawer_events SET cashier_session_id=$session WHERE request_id='sale-fixture'","sale session",("$other",otherSession),("$session",session));AssertTamperBlocked(c,drawer,user,"DELETE FROM cash_drawer_events WHERE request_id='sale-fixture'",null,"missing sale event");InsertSourceEvent(c,session,"CashSaleNet",1,500,"Sale",sale.ToString("D"),user,"Cash","sale-fixture-2");
        Guid customer=Guid.NewGuid();Exec(c,"INSERT INTO customers(id,full_name,is_active,created_by_user_id,created_at,updated_at) VALUES($id,'W4 Customer',1,$user,$at,$at)",("$id",customer.ToString("D")),("$user",user.ToString("D")),("$at",now));Guid ar=Guid.NewGuid();Exec(c,"INSERT INTO accounts_receivable_collections(id,customer_id,amount_cents,method,collected_by_user_id,collected_at,cashier_session_id) VALUES($id,$customer,300,'Cash',$user,$at,$session)",("$id",ar.ToString("D")),("$customer",customer.ToString("D")),("$user",user.ToString("D")),("$at",now),("$session",session));InsertSourceEvent(c,session,"ArCashCollection",1,300,"ArCollection",ar.ToString("D"),user,"Cash","ar-fixture");AssertTamperBlocked(c,drawer,user,"UPDATE cash_drawer_events SET amount_cents=301 WHERE request_id='ar-fixture'","UPDATE cash_drawer_events SET amount_cents=300 WHERE request_id='ar-fixture'","AR amount");AssertTamperBlocked(c,drawer,user,"UPDATE cash_drawer_events SET method='Card' WHERE request_id='ar-fixture'","UPDATE cash_drawer_events SET method='Cash' WHERE request_id='ar-fixture'","AR method");AssertTamperBlocked(c,drawer,user,"DELETE FROM cash_drawer_events WHERE request_id='ar-fixture'",null,"missing AR event");InsertSourceEvent(c,session,"ArCashCollection",1,300,"ArCollection",ar.ToString("D"),user,"Cash","ar-fixture-2");Exec(c,"INSERT INTO accounts_receivable_collections(id,customer_id,amount_cents,method,collected_by_user_id,collected_at,cashier_session_id) VALUES($id,$customer,200,'Card',$user,$at,$session)",("$id",Guid.NewGuid().ToString("D")),("$customer",customer.ToString("D")),("$user",user.ToString("D")),("$at",now),("$session",session));var close=drawer.Close(user,new(800,true,"source-close","Verified sources"));Require(close.IsSuccess&&close.Value.ExpectedCashCents==800&&close.Value.VarianceCents==0,"exact sale and AR sources must close verified; noncash adds zero");
    }
    private static void AssertTamperBlocked(SalrynLocalComposition c,CashDrawerReconciliationService drawer,Guid user,string tamper,string? restore,string label,params(string,object)[] p){Exec(c,tamper,p);Require(drawer.Close(user,new(0,true,"tamper-"+Guid.NewGuid().ToString("N"),null)).IsFailure,label+" mismatch must block verified close");if(restore is not null)Exec(c,restore,p);}
    private static void InsertSourceEvent(SalrynLocalComposition c,string session,string type,int direction,long amount,string sourceType,string sourceId,Guid actor,string method,string request)=>Exec(c,"INSERT INTO cash_drawer_events(id,cashier_session_id,event_type,direction,amount_cents,source_type,source_id,actor_user_id,method,occurred_at,request_id,note) VALUES($id,$session,$type,$direction,$amount,$sourceType,$source,$actor,$method,$at,$request,'fixture')",("$id",Guid.NewGuid().ToString("D")),("$session",session),("$type",type),("$direction",direction),("$amount",amount),("$sourceType",sourceType),("$source",sourceId),("$actor",actor.ToString("D")),("$method",method),("$at",DateTimeOffset.UtcNow.ToString("O")),("$request",request));
    private static void RunV25ToV26MigrationCheck(){string root=Path.Combine(Path.GetTempPath(),"salryn-w4-v25-"+Guid.NewGuid().ToString("N"));try{var c=SalrynLocalComposition.Create(DbPaths.CreateDevelopment(root));Require(c.DatabaseInitialization.InitializeDatabase().IsSuccess,"migration fixture initialization must pass");Guid user=SeedUser(c,"w4-migration");Guid session=Guid.NewGuid();string at=DateTimeOffset.UtcNow.ToString("O");Exec(c,"INSERT INTO cashier_sessions(id,user_id,opened_at,closed_at,opening_cash_cents,expected_cash_cents,counted_cash_cents,variance_cents,status,notes,cash_coverage_started_at) VALUES($id,$user,$at,$at,0,0,0,0,2,'Restored note',$at)",("$id",session.ToString("D")),("$user",user.ToString("D")),("$at",at));Exec(c,"INSERT INTO cash_drawer_reconciliations(cashier_session_id,expected_cash_cents,counted_cash_cents,variance_cents,coverage_status,review_status,close_request_id,submitted_by_user_id,submitted_at,confirmation_text) VALUES($session,0,0,0,'Verified','Reconciled','v25-close',$user,$at,'Operator confirmed physical cash count')",("$session",session.ToString("D")),("$user",user.ToString("D")),("$at",at));Exec(c,"ALTER TABLE cash_drawer_reconciliations DROP COLUMN close_note; DELETE FROM schema_migrations WHERE version=26;");Require(c.DatabaseInitialization.InitializeDatabase().IsSuccess,"v25-to-v26 migration must pass");using var x=c.ConnectionFactory.CreateConnection();x.Open();using var q=x.CreateCommand();q.CommandText="SELECT close_note FROM cash_drawer_reconciliations WHERE cashier_session_id=$session";q.Parameters.AddWithValue("$session",session.ToString("D"));Require((string?)q.ExecuteScalar()=="Restored note","v26 migration must backfill canonical close note");}finally{SqliteConnectionFactory.ClearAllPools();if(Directory.Exists(root))Directory.Delete(root,true);}}
    private static Guid SeedUser(SalrynLocalComposition c,string username="w4"){Guid id=Guid.NewGuid();using var x=c.ConnectionFactory.CreateConnection();x.Open();using var q=x.CreateCommand();q.CommandText="INSERT INTO users(id,username,display_name,password_hash,role_id,status,created_at) VALUES($id,$username,'W4','x',(SELECT id FROM roles LIMIT 1),1,$at)";q.Parameters.AddWithValue("$id",id.ToString("D"));q.Parameters.AddWithValue("$username",username);q.Parameters.AddWithValue("$at",DateTimeOffset.UtcNow.ToString("O"));q.ExecuteNonQuery();return id;}
    private static void Exec(SalrynLocalComposition c,string sql,params(string,object)[] p){using var x=c.ConnectionFactory.CreateConnection();x.Open();using var q=x.CreateCommand();q.CommandText=sql;foreach(var a in p)q.Parameters.AddWithValue(a.Item1,a.Item2);q.ExecuteNonQuery();}
    private static long Scalar(SalrynLocalComposition c,string sql,params(string,object)[] p){using var x=c.ConnectionFactory.CreateConnection();x.Open();using var q=x.CreateCommand();q.CommandText=sql;foreach(var a in p)q.Parameters.AddWithValue(a.Item1,a.Item2);return Convert.ToInt64(q.ExecuteScalar());}
    private static long Count(SalrynLocalComposition c,string table)=>Scalar(c,$"SELECT COUNT(*) FROM {table}");
    private static string Root(){string? p=Directory.GetCurrentDirectory();while(p is not null&&!File.Exists(Path.Combine(p,"Salryn.sln")))p=Directory.GetParent(p)?.FullName;return p!;}
    private static void Require(bool ok,string message){if(!ok)throw new InvalidOperationException(message);}
}
